<?php require __DIR__.'/../layout.php'; ?><section class="card form-card"><h2><?= !empty($item['id'])?'Edit Barang':'Tambah Barang' ?></h2><?php if($error): ?><p class="error"><?= htmlspecialchars($error) ?></p><?php endif; ?><form method="post" action="index.php?module=barang&action=save"><input type="hidden" name="csrf" value="<?= htmlspecialchars($_SESSION['csrf']) ?>"><input type="hidden" name="id" value="<?= (int)($item['id']??0) ?>"><label>Nama barang<input name="nama" maxlength="150" required value="<?= htmlspecialchars($item['nama']??'') ?>"></label><label>Kategori<select name="kategori_id" required><option value="">Pilih kategori</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)($item['kategori_id']??0)===(int)$c['id']?'selected':'' ?>><?= htmlspecialchars($c['nama']) ?></option><?php endforeach; ?></select></label><label>Harga<input type="number" name="harga" min="0" step="0.01" required value="<?= htmlspecialchars((string)($item['harga']??'')) ?>"></label><label>Stok<input type="number" name="stok" min="0" step="1" required value="<?= htmlspecialchars((string)($item['stok']??'')) ?>"></label><div class="top"><a href="index.php?module=barang">Batal</a><button class="btn">Simpan</button></div></form></section></main></div></body></html>
